patches.good:
diff --git a/src/bootstrap.ts b/src/bootstrap.ts
index 1f9c352..bc821b5 100644
--- a/src/bootstrap.ts
+++ b/src/bootstrap.ts
@@ -1,14 +1,41 @@
-export function normalizeHookNames(input: unknown): string[] {
-  void input;
-  throw new Error("not implemented");
+function listOfStrings(value: unknown): string[] {
+  if (!Array.isArray(value)) {
+    return [];
+  }
+  return value.filter((item): item is string => typeof item === "string");
 }

-export function findMissing(input: unknown): string[] {
-  void input;
-  throw new Error("not implemented");
+function sortedUnique(items: readonly string[]): string[] {
+  return [...new Set(items)].sort();
+}
+export function checkBootstrap(input: unknown): { ok: boolean; missing: string[] } {
+  if (typeof input !== "object" || input === null || Array.isArray(input)) {
+    return { ok: false, missing: [] };
+  }
+  const rec = input as Record<string, unknown>;
+  const required = listOfStrings(rec.required);
+  const installed = new Set(listOfStrings(rec.installed));
+  const missing = sortedUnique(required.filter((name) => !installed.has(name)));
+  return { ok: missing.length === 0, missing };
 }

-export function checkBootstrap(input: unknown): unknown {
-  void input;
-  throw new Error("not implemented");
+export function normalizeHookNames(input: unknown): string[] {
+  return sortedUnique(listOfStrings(input).map((name) => name.toLowerCase().trim()));
+}
+
+export function findMissing(input: unknown): string[] {
+  if (!Array.isArray(input)) {
+    return [];
+  }
+  const missing: string[] = [];
+  for (const item of input) {
+    if (typeof item !== "object" || item === null || Array.isArray(item)) {
+      continue;
+    }
+    const rec = item as Record<string, unknown>;
+    if (typeof rec.name === "string" && rec.installed !== true) {
+      missing.push(rec.name);
+    }
+  }
+  return sortedUnique(missing);
 }

